      <h3 className="course__title">{title}</h3>
      {badge}
    </div>
    <p className="course__meta">{hours}시간</p>
  </article>
);

const newBadge = <Badge label="신규" />;

root.render(
  <>
    <Course title="자바스크립트 입문" hours={12} badge={newBadge} />
    <Course title="CSS 레이아웃" hours={8} />
  </>
);

